import{BASE_COATS,COATS,EVOLUTION,newGame,move,spawn,canMove}from'./core.mjs';
const $=id=>document.getElementById(id),KEY='catvolution.v2';let starter=null,board=[],score=0,undo=null,sound=true,audio;
function load(){try{const s=JSON.parse(localStorage.getItem(KEY)||'{}');sound=s.sound!==false;starter=COATS[s.starter]?s.starter:null;$('best').textContent=Number(s.best)||0}catch{}}
function save(){try{const old=JSON.parse(localStorage.getItem(KEY)||'{}');localStorage.setItem(KEY,JSON.stringify({sound,starter,best:Math.max(Number(old.best)||0,score)}))}catch{}}
function stage(value){return value>=512?'giant':value>=32?'adult':'kitten'}
function image(coat,value=2){const suffix=stage(value)==='kitten'?'':`-${stage(value)}`;return`cats/${coat}${suffix}.webp`}
function beep(){if(!sound)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=520;g.gain.setValueAtTime(.04,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.09);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.1)}catch{}}
function renderOptions(){$('cat-options').innerHTML=BASE_COATS.map(c=>`<button class="cat-card" data-coat="${c}" aria-pressed="${starter===c}"><img src="${image(c)}" alt="${COATS[c][0]}"><div><strong>${COATS[c][0]}</strong><span>${COATS[c][1]}</span></div></button>`).join('');document.querySelectorAll('[data-coat]').forEach(b=>b.onclick=()=>{starter=b.dataset.coat;save();renderOptions();$('start').disabled=false})}
function renderGuide(){$('collection-grid').innerHTML=Object.entries(EVOLUTION).map(([value,label])=>`<article class="collection-card"><img src="${starter?image(starter,Number(value)):image('orange',Number(value))}" alt="${label}"><div><strong>${value} · ${label}</strong><small>${Number(value)>=512?'Legendary size':'Keep merging to grow.'}</small></div></article>`).join('')}
function render(){const max=Math.max(2,...board.filter(Boolean).map(t=>t.value));$('board').innerHTML=board.map(t=>`<div class="cell">${t?`<div class="tile ${t.value>=1024?'king':''} ${t.value>=2048?'god':''}"><img src="${image(t.coat,t.value)}" alt=""><span class="coat-dot">${EVOLUTION[t.value]||'Legendary'}</span><b class="value">${t.value}</b></div>`:''}</div>`).join('');$('score').textContent=score;$('best').textContent=Math.max(Number($('best').textContent)||0,score);$('highest').textContent=`${EVOLUTION[max]||'Legendary Cat'} · ${max}`;$('undo').disabled=!undo;save()}
function begin(){if(!starter)return;board=newGame(starter);score=0;undo=null;$('select-screen').hidden=true;$('game-screen').hidden=false;$('status').textContent=`Every tile is your ${COATS[starter][0]}. Merge equal ages to help it grow.`;render()}
function act(direction){const before=board.map(t=>t&&({...t})),previousScore=score;const result=move(board,direction);if(!result.changed)return;undo={board:before,score:previousScore};board=spawn(result.board,starter);score+=result.score;if(result.score){beep();const max=Math.max(...board.filter(Boolean).map(t=>t.value));const messages={4:'Four months old. Still innocent-ish.',8:'Eight months old. Curtains are now prey.',16:'One year old. Fully licensed chaos.',64:'Your cat has discovered food.',128:'Chonk level increasing.',256:'The vet is concerned.',512:'This is no longer a house cat.',1024:'ALL HAIL THE CAT KING.',2048:'YOUR CAT HAS ASCENDED.'};if(messages[max])$('status').textContent=messages[max]}render();if(!canMove(board))$('game-over').showModal()}
load();renderOptions();renderGuide();$('start').disabled=!starter;$('start').onclick=begin;$('random').onclick=()=>{starter=BASE_COATS[Math.floor(Math.random()*BASE_COATS.length)];renderOptions();$('start').disabled=false};$('home').onclick=()=>{$('game-screen').hidden=true;$('select-screen').hidden=false;renderOptions()};$('restart').onclick=begin;$('again').onclick=()=>{$('game-over').close();begin()};$('undo').onclick=()=>{if(!undo)return;board=undo.board;score=undo.score;undo=null;$('status').textContent='Time reversed. Your cat is younger again.';render()};$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',sound);save()};$('sound').textContent=sound?'Sound on':'Sound off';$('collection-open').onclick=()=>{renderGuide();$('collection').showModal()};$('collection-close').onclick=()=>$('collection').close();
const dirs={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down'};addEventListener('keydown',e=>{if(!$('game-screen').hidden&&dirs[e.key]){e.preventDefault();act(dirs[e.key])}});let sx=0,sy=0;$('board').addEventListener('pointerdown',e=>{sx=e.clientX;sy=e.clientY});$('board').addEventListener('pointerup',e=>{const dx=e.clientX-sx,dy=e.clientY-sy;if(Math.max(Math.abs(dx),Math.abs(dy))<25)return;act(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up')});
